args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?film ?filmLabel ?director ?directorLabel ?birth WHERE {
  VALUES ?film { dbr:Pod_bandera_milosci dbr:World_in_My_Corner }
  ?film dbo:director ?director .
  OPTIONAL { ?director dbo:birthDate ?bd1 }
  OPTIONAL { ?director dbp:birthDate ?bd2 }
  BIND(COALESCE(?bd1, ?bd2) AS ?birth)
  OPTIONAL { ?film rdfs:label ?filmLabel }
  OPTIONAL { ?director rdfs:label ?directorLabel }
} ORDER BY ?film

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?film ?director ?directorLabel ?birth WHERE {
  VALUES ?film { dbr:Pod_bandera_milosci dbr:World_in_My_Corner }
  ?film dbo:director ?director .
  OPTIONAL { ?director dbo:birthDate ?bd1 }
  OPTIONAL { ?director dbp:birthDate ?bd2 }
  BIND(COALESCE(?bd1, ?bd2) AS ?birth)
  OPTIONAL { ?director rdfs:label ?directorLabel FILTER(lang(?directorLabel) = "en" || lang(?directorLabel) = "") }
} ORDER BY ?film

